function plannerProfileText(){const p=state.profile;return[p.skills,p.experience,p.certificates].map(x=>String(x||'')).join(' ').toLowerCase()}
function plannerDegreeRank(value){const v=String(value||'').toLowerCase();if(!v)return null;if(v.includes('博士'))return 5;if(v.includes('硕士'))return 4;if(v.includes('本科')||v.includes('bachelor'))return 3;if(v.includes('大专')||v.includes('associate'))return 2;if(v.includes('高中')||v.includes('中专')||v.includes('中学'))return 1;if(v.includes('无正式')||v.includes('自学')||v.includes('职业培训')||v.includes('其他 / 自定义'))return 0;return null}
function plannerAssess(job,c){const p=state.profile,text=plannerProfileText(),empty={status:'verify',reason:'个人资料不足以比较；补充信息或查看原始公告后再确认。'};if(c.type==='noDegree')return{status:'met',reason:'该职位明确不设正式学历门槛；不会因缺少学位而判为不符合。'};if(c.type==='years'){const raw=p[c.field];if(raw===''||raw==null)return empty;const n=Number(raw);return n>=c.min?{status:'met',reason:'已填写 '+n+' 年，达到公告列出的至少 '+c.min+' 年。'}:{status:'gap',reason:'已填写 '+n+' 年，低于公告门槛；请核实可计入的相关经历。'}}if(c.type==='degree'){const rank=plannerDegreeRank(p.degree);if(rank==null)return empty;return rank>=c.min?{status:'met',reason:'已填写的学历层级达到公告最低层级。'}:{status:'gap',reason:'已填写的学历层级低于公告门槛；等同资格或在读情况请向招聘方确认。'}}if(c.type==='optionalDegree')return{status:'optional',reason:'这是优先条件，不属于基本学历门槛。'};if(c.type==='major'){if(!p.major)return empty;const hit=c.keywords.some(x=>String(p.major).toLowerCase().includes(x.toLowerCase()));return hit?{status:'met',reason:'专业名称命中相关领域关键词；专业等同性仍需按招聘方口径确认。'}:{status:'verify',reason:'简单关键词无法确认专业等同性；请向招聘方核实，不会据此自动淘汰。'}}if(c.type==='gradYear'){if(!p.gradDate)return empty;return Number(String(p.gradDate).slice(0,4))===c.year?{status:'met',reason:'毕业年份与职位标题标注的 '+c.year+' 届一致；具体日期窗口仍需确认。'}:{status:'gap',reason:'毕业年份与职位标题标注的 '+c.year+' 届不同；请核实招聘方对届别的定义。'}}if(c.type==='monthWindow'){if(!p.gradDate)return empty;return String(p.gradDate)>=c.start&&String(p.gradDate)<=c.end?{status:'met',reason:'毕业月份在此历史公告列出的区间内；当前招聘资格仍需核实。'}:{status:'gap',reason:'毕业月份超出此历史公告的区间；该样例不能代表当前招聘要求。'}}if(c.type==='skillsAny'||c.type==='preferredAny'){const hits=c.keywords.filter(x=>text.includes(x.toLowerCase()));if(c.type==='preferredAny')return hits.length?{status:'optionalmet',reason:'资料中找到 '+hits.join('、')+'；这是公告中的优先项。'}:{status:'optional',reason:'这是加分项而非硬性门槛；未找到关键词不代表被淘汰。'};if(hits.length)return{status:'met',reason:'个人资料中找到 '+hits.join('、')+'；请准备可验证的项目 / 工作证据。'};return text?{status:'verify',reason:'简历文字未找到公告关键词；请人工核对同义技能并补充证据。'}:empty}if(c.type==='skillsAll'){const missing=c.keywords.filter(x=>!text.includes(x.toLowerCase()));return missing.length?{status:'verify',reason:'尚未找到：'+missing.join('、')+'。关键词匹配无法判断真实熟练度，请核对经历。'}:{status:'met',reason:'个人资料中找到全部列出的关键词；仍需有项目 / 工作证据。'}}if(c.type==='confirm'||c.type==='sensitiveConfirm')return{status:'verify',reason:c.type==='sensitiveConfirm'?'此审查不能从个人资料自动推断；请查看官方说明，不要在此输入敏感信息。':'需由你判断排班是否适合；公告未说明你的个人可用时间。'};return{status:'verify',reason:'导入的招聘条件需打开原文并逐项核实。'}}
function plannerCounts(job){const a=(job.criteria||[]).filter(x=>x.essential!==false).map(c=>plannerAssess(job,c));return{met:a.filter(x=>x.status==='met').length,gap:a.filter(x=>x.status==='gap').length,verify:a.filter(x=>x.status==='verify').length}}
function plannerSummary(job){if(!job.criteria||!job.criteria.length)return'手动条件尚待逐项核实';const n=plannerCounts(job);return'基本条件：'+n.met+' 项符合 · '+n.gap+' 项差距 · '+n.verify+' 项待核实（不计算录用概率）'}
function plannerLabel(s){return({met:'符合',gap:'存在差距',verify:'待核实',optional:'优先项',optionalmet:'优先项有证据'})[s]||'待核实'}
function plannerClass(s){return s==='met'?'met':s==='gap'?'gap':s==='optional'||s==='optionalmet'?'na':'verify'}
function plannerStandardsHTML(){const cards=plannerStandards.map(j=>'<article class="standard-card"><div class="standard-company">'+esc(j.company)+'</div><h4>'+esc(j.title)+'</h4><p class="standard-note">'+esc(j.family)+' · 原文核对 '+esc(j.checkedDate)+'</p><div class="standard-assessment">'+esc(plannerSummary(j))+'</div><p class="standard-note">'+esc(j.postingStatus)+'</p><div class="standard-actions"><a class="btn btn-small" href="'+esc(safeUrl(j.link))+'" target="_blank" rel="noopener noreferrer">公司 / 招聘原文 ↗</a><button class="btn btn-small btn-primary" data-action="screen" data-id="'+esc(j.id)+'">按我的资料核对</button></div></article>').join('');return'<section class="form-section"><div class="form-section-head"><span class="form-number">06</span><div><h3>真实公司筛选标准样例</h3><p>公开职位原文链接与条件快照；按已填写信息作辅助判断。</p></div></div><div class="standard-grid">'+cards+'</div><p class="field-hint">页面核对日期：2026-10-27。职位状态和要求会变化，部分样例已关闭。文字匹配无法确认资格、熟练度或录用可能；“待核实”请查看原文或询问雇主。</p></section>'}
const plannerOriginalProfile=profileHTML;
profileHTML=function(){let html=plannerOriginalProfile();html=html.replace('<h3>教育背景</h3><p>记录可能影响学历、专业和毕业批次筛选的信息。</p>','<h3>教育与培训（可选）</h3><p>不同职业对学历要求不同；没有正式学历也可以继续使用本工具。</p>').replace('<label for="pSchool">学校</label>','<label for="pSchool">学校 / 培训机构（可选）</label>').replace('placeholder="学校名称"','placeholder="可留空"').replace('<label for="pDegree">最高学历 / 当前学历</label>','<label for="pDegree">学历 / 受训情况（可选）</label>').replace('<label for="pMajor">专业 / 研究方向</label>','<label for="pMajor">专业 / 研究领域 / 技艺（可选）</label>').replace('<label for="pGrad">预计毕业时间</label>','<label for="pGrad">毕业 / 资格取得时间（若适用）</label>').replace('<label for="pExperience">实习、工作、科研或项目经历</label>','<label for="pExperience">工作、照护、学习项目、社区或志愿经历</label>').replace('<span class="field-hint">没有正式实习也可以填写课程项目、社团、竞赛、志愿服务或个人作品。</span></div>','<span class="field-hint">有薪或无薪工作、照护、社区、自由职业、学习项目和志愿经历都可记录；没有也可留空。</span><div class="form-grid"><div class="field"><label>目标岗位相关全职年限（可选）</label><input name="workYears" type="number" min="0" max="80" step="0.5" value="'+fieldValue('workYears')+'" placeholder="如 3.5"></div><div class="field"><label>目标领域专业年限（可选）</label><input name="specializedYears" type="number" min="0" max="80" step="0.5" value="'+fieldValue('specializedYears')+'" placeholder="如 3"></div><div class="field"><label>设计 / 架构年限（若适用）</label><input name="architectureYears" type="number" min="0" max="80" step="0.5" value="'+fieldValue('architectureYears')+'" placeholder="可留空"></div></div></div>');
const ds=html.indexOf('<select id="pDegree" name="degree">'),de=html.indexOf('</select>',ds)+9;if(ds>=0&&de>=9){const opts=['无正式学历 / 自学','职业培训 / 资格','高中 / 中专','大专','本科','硕士','博士','其他 / 自定义'].map(x=>'<option'+(state.profile.degree===x?' selected':'')+'>'+esc(x)+'</option>').join('');html=html.slice(0,ds)+'<select id="pDegree" name="degree"><option value="">请选择或留空</option>'+opts+'</select>'+html.slice(de)}
const stage='<div class="field"><label for="pCareerStage">你目前的阶段（可选）</label><select id="pCareerStage" name="careerStage"><option value="">暂不确定</option>'+['在校或培训中','正在工作','寻找第一份工作','考虑转行','重返职场','自由职业 / 创业','其他阶段'].map(x=>'<option'+(state.profile.careerStage===x?' selected':'')+'>'+esc(x)+'</option>').join('')+'</select></div><div class="field">';
html=html.replace('<div class="field"><label for="pSchool">',stage+'<label for="pSchool">').replace('<label for="pBudget">升学预算 / 家庭能支持的范围（可选）</label>','<label for="pBudget">继续教育 / 培训 / 转型预算（可选）</label>').replace('把家人的期待当作讨论条件，而不是替你做决定的结论。','家人或重要支持者的意见可作讨论参考；也可以只记录个人现实约束。').replace('<label for="pFamilyNote">家庭的具体意见 / 不能接受的条件</label>','<label for="pFamilyNote">家庭或重要支持者的意见 / 现实约束（可选）</label>').replace('</form>',plannerStandardsHTML()+'</form>');return html};
const plannerOldBindProfile=bindProfile;
bindProfile=function(){plannerOldBindProfile();const f=document.getElementById('profileForm');if(!f)return;const sync=()=>{['workYears','specializedYears','architectureYears','careerStage'].forEach(k=>{const e=f.elements[k];if(e)state.profile[k]=e.value});save()};f.addEventListener('input',sync);f.addEventListener('change',sync)};
function readinessRows(){const p=state.profile;return[
{id:'education',name:'学历 / 专业 / 可替代资格',kind:'按目标岗位核对',evidence:'学历不是所有岗位的通用门槛。核对职位原文的最低学历、专业或受监管资格；没有学历要求时标记“不适用”。'},
{id:'graduation',name:'毕业届别 / 到岗时间',kind:'部分岗位硬筛选',evidence:'校招、培训项目和特定签证可能有日期窗口；有工作经验或转职岗位通常不应默认要求应届身份。'},
{id:'authorization',name:'身份 / 工作许可',kind:'按地区与岗位核对',evidence:p.workAuth?'按目标地区核实工作许可、雇主担保或特定身份。':'跨地区求职时再填写愿意共享的工作许可信息；不适用可跳过。'},
{id:'location',name:'地点 / 时间 / 照护约束',kind:'个人可行条件',evidence:p.targetMarkets?'目标地点：'+p.targetMarkets+'；核实现场、远程、轮班、差旅或搬迁要求。':'按实际需要补充地点、工作时间、远程安排或照护约束。'},
{id:'academic',name:'成绩 / GPA / 排名',kind:'仅在公告要求时核对',evidence:'很多工作不要求 GPA。只有具体公告列出阈值时才比较。'},
{id:'language',name:'语言 / 沟通要求',kind:'岗位条件',evidence:p.language?'核对语言等级、使用情境和可接受证明。':'不同工作对语言的要求不同；可用工作样例或证书补充证据。'},
{id:'skills',name:'技能 / 工具 / 可迁移能力',kind:'岗位条件',evidence:p.skills?'将技能对应到可验证的工作、项目或生活实践证据。':'按职位说明提取技能，不限于正式工作或学校项目。'},
{id:'qualifications',name:'执照 / 证书 / 背景审查',kind:'部分岗位法律或硬性要求',evidence:'受监管职业或特定岗位可能要求资格；背景审查不应一概套用到所有工作。'},
{id:'experience',name:'经验年限 / 经验类型',kind:'按职位级别核对',evidence:p.workYears!==''?'已填写岗位相关工作年限 '+p.workYears+' 年；其他经历是否计入须看公告。':'有薪、无薪、项目、自由职业与照护经历的可计入方式因岗位而异。'},
{id:'materials',name:'简历 / 作品 / 证明材料',kind:'申请材料',evidence:'核对联系方式、日期、职责、成果和附件；按岗位需要提交简历、作品、资格或推荐材料。'}]}
function profileScore(){const p=state.profile,f=[p.careerStage,p.degree||p.major,p.experience||p.workYears,p.skills,p.directions&&p.directions.length,p.targetMarkets,p.workStyle,p.personalNote,p.familyNote||p.studyBudget];return Math.round(f.filter(x=>x&&String(x).trim()).length/f.length*100)}
function updateMini(){const p=state.profile,n=profileScore();document.getElementById('miniProgress').style.width=n+'%';document.getElementById('miniPercent').textContent=n+'%';document.getElementById('miniLabel').textContent=p.name?String(p.name)+' 的生涯档案':'先从你的经历与目标开始'}
function nextAction(){const p=state.profile;if(!(p.directions||[]).length)return{title:'选出你愿意先验证的 1–3 个工作或学习方向',copy:'可按行业、岗位、工作条件或生活目标描述，不需要先确定长期职业。',page:'profile'};if(!String(p.experience||'').trim()&&!p.workYears)return{title:'整理一段能展示能力的经历',copy:'可写工作、照护、志愿服务、个人项目、社区参与或培训实践。',page:'profile'};if(!state.jobs.some(j=>!j.sample))return{title:'查看真实公司筛选标准并比较条件',copy:'打开公司原文，查看哪些要求符合、哪些还需核实，再决定下一步。',page:'jobs'};return{title:'核对优先职位的真实要求',copy:'分别记录证据、待核实项和工作条件，按实际反馈调整计划。',page:'jobs'}}
function taskSuggestions(){const p=state.profile;return[
{id:'t-goal',title:(p.directions||[]).length?'从一个目标方向挑 2–3 个真实岗位作比较':'用行业、任务类型或工作条件写下 1–3 个探索方向'},
{id:'t-criteria',title:'打开公司职位原文，核对最低学历、经验、许可和资格要求'},
{id:'t-evidence',title:'把工作、照护、志愿或项目经历写成行动与结果'},
{id:'t-skills',title:'挑出 3 项岗位要求的技能，分别补上可验证的证据'},
{id:'t-constraints',title:'写下个人的时间、地点、收入和照护底线'},
{id:'t-options',title:'比较工作、学习 / 培训、转型或重返工作的成本与时间'},
{id:'t-review',title:'一周后复盘：哪些信息已从猜测变成证据？'}]}
const plannerOriginalOverview=overviewHTML;
overviewHTML=function(){return plannerOriginalOverview().split('把兴趣变成岗位目标，并优先确认校招资格。').join('从兴趣、能力和工作条件出发，比较不同类型的岗位与路径。').split('直接就业 / 校招').join('进入 / 更换工作').split('支持导入招聘筛选表').join('含公开标准样例与个人岗位').split('已整理目标岗位').join('岗位样例与个人岗位')};
const plannerOriginalJobs=jobsHTML;
jobsHTML=function(){return plannerOriginalJobs().split('把招聘公告里的必填条件逐项拆开，标记已满足、待核实或存在差距。').join('按真实招聘页面拆解条件，并结合个人背景辅助判断。').split('招聘信息以公告为准。').join('招聘信息以雇主原文为准。').split('核对结果由你手动标记，本工具不自动判断签证资格或录用概率。').join('系统仅作文字和数字的初步比较，不判断录用概率、签证资格或专业等同性；请打开招聘原文核实。')};
function renderJobGrid(){const host=document.getElementById('jobGrid');if(!host)return;const list=state.jobs.filter(j=>{const q=(state.search||'').trim().toLowerCase(),hay=(j.company+' '+j.title+' '+(j.location||'')+' '+(j.market||'')).toLowerCase();if(q&&!hay.includes(q))return false;if(state.market!=='all'&&normalizeMarket(j)!==state.market)return false;if(state.jobFilter==='saved'&&!state.savedJobs.includes(j.id))return false;if(state.jobFilter==='verify'&&j.criteria&&plannerCounts(j).verify===0)return false;return true}),cnt=document.getElementById('jobCount');if(cnt)cnt.textContent=list.length+' / '+state.jobs.length+' 个岗位';if(!list.length){host.innerHTML='<div class="empty-note">没有符合当前筛选条件的岗位。试试清空搜索或切换市场。</div>';return}host.innerHTML='<div class="job-grid">'+list.map(j=>{const st=statusForJob(j),saved=state.savedJobs.includes(j.id);return'<article class="job-card"><div class="job-head"><div><div class="job-company">'+esc(j.company)+'</div><div class="job-title">'+esc(j.title)+'</div></div><button class="icon-button" data-action="favorite" data-id="'+esc(j.id)+'" aria-label="'+(saved?'取消收藏':'收藏岗位')+'">'+(saved?'★':'☆')+'</button></div><div class="job-badges"><span class="pill '+st.cls+'">'+esc(st.label)+'</span>'+(j.family?'<span class="pill blue">'+esc(j.family)+'</span>':'')+(j.sample?'<span class="pill gray">公开标准样例</span>':'')+'</div><div class="assessment-summary"><b>资料对照</b>：'+esc(j.criteria?plannerSummary(j):'导入条件尚待人工核对')+'</div><div class="job-meta"><span>⌖ '+esc(j.location||j.market||'地点待补充')+'</span><span>◷ '+esc(j.sample?'原文核对：'+j.checkedDate:'来源日期：'+(j.checkedDate||'未记录'))+'</span></div><p class="job-why">'+esc(j.eligibility||j.requirements||'打开招聘公告后，逐项核实职位要求。').slice(0,260)+'</p><div class="job-footer"><span class="job-source">'+(j.sample?'公开页面条件快照；状态请看原文':'由你添加；请查看原始职位公告')+'</span><div class="job-actions">'+(j.link?'<a class="btn btn-small" href="'+esc(safeUrl(j.link))+'" target="_blank" rel="noopener noreferrer">原文 ↗</a>':'')+'<button class="btn btn-small btn-primary" data-action="screen" data-id="'+esc(j.id)+'">按我的资料核对</button></div></div></article>'}).join('')+'</div>'}
function plannerCriteria(job){return job.criteria&&job.criteria.length?job.criteria:splitCriteria(job.requirements||'').map((x,i)=>({id:'import-'+i,title:'招聘方条件 '+(i+1),type:'manual',essential:true,requirement:x}))}
function screenDialog(job){const saved=state.jobChecks[job.id]||{},criteria=plannerCriteria(job),items=criteria.map(c=>{const r=plannerAssess(job,c),manual=saved[c.id]||'verify';return'<article class="assessed-criterion"><div class="criterion-heading"><div><b>'+esc(c.title)+'</b><span class="criterion-kind">'+(c.essential===false?'优先项':'基本条件')+'</span></div><span class="result-badge '+plannerClass(r.status)+'">'+plannerLabel(r.status)+'</span></div><p class="criterion-requirement">'+esc(c.requirement||c.sourceText||'查看招聘方原文确认。')+'</p><p class="criterion-reason">'+esc(r.reason)+'</p><div class="criterion-review"><span>我的人工复核</span><select data-check="'+esc(c.id)+'" data-job="'+esc(job.id)+'"><option value="verify" '+(manual==='verify'?'selected':'')+'>待核实</option><option value="met" '+(manual==='met'?'selected':'')+'>已确认符合</option><option value="gap" '+(manual==='gap'?'selected':'')+'>已确认存在差距</option><option value="na" '+(manual==='na'?'selected':'')+'>不适用</option></select></div></article>'}).join('');document.getElementById('screenDialogBody').innerHTML='<div class="modal-head"><div><div class="eyebrow">招聘方公开标准 · 个人资料辅助比对</div><h2>'+esc(job.company)+' · '+esc(job.title)+'</h2><p>'+esc(job.location||job.market||'地点未注明')+'　｜　来源核对：'+esc(job.checkedDate||'未记录')+'</p></div><button class="icon-button" data-action="close-screen" aria-label="关闭">×</button></div><div class="source-callout"><div><b>岗位状态：</b>'+esc(job.postingStatus||job.status||'打开职位原文确认')+'</div><div><b>判断说明：</b>'+esc(job.criteria?plannerSummary(job):'导入条件需人工确认')+'</div>'+(job.link?'<div class="standard-actions"><a class="btn btn-small btn-primary" href="'+esc(safeUrl(job.link))+'" target="_blank" rel="noopener noreferrer">打开公司 / 招聘原文 ↗</a></div>':'')+'</div><div class="assessed-list">'+items+'</div><p class="modal-note">“符合 / 差距 / 待核实”只比较你填写的资料和页面文字。未识别关键词不等于不符合；资历等同、工作许可、专业目录、背景审查和职位状态需看原文或向雇主确认。个人画像只保存在此浏览器，不计算录用概率。</p>';document.getElementById('screenDialog').showModal()}
const plannerStyle=document.createElement('style');plannerStyle.textContent='.standard-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:12px}.standard-card{border:1px solid var(--line);border-radius:14px;background:#fff;padding:14px;min-width:0}.standard-card h4{font-size:13px;margin:7px 0 4px;color:var(--ink);line-height:1.4}.standard-company{font-size:10px;font-weight:750;color:var(--green)}.standard-note{font-size:10px;line-height:1.5;color:#718077;margin:5px 0}.standard-assessment{font-size:10px;line-height:1.6;color:var(--ink);background:#f5f7f4;border-radius:8px;padding:8px;margin:8px 0}.standard-actions{display:flex;gap:7px;flex-wrap:wrap;align-items:center;margin-top:9px}.assessment-summary{font-size:10px;line-height:1.55;color:var(--ink);background:#f5f7f4;border-radius:8px;padding:8px;margin:9px 0}.assessed-list{display:grid;gap:9px;margin:14px 0}.assessed-criterion{border:1px solid var(--line);border-radius:12px;padding:12px;background:white}.criterion-heading{display:flex;justify-content:space-between;align-items:center;gap:10px}.criterion-heading b{font-size:12px;color:var(--ink)}.criterion-kind{font-size:9px;color:#7b8980;margin-left:8px}.result-badge{white-space:nowrap;border-radius:999px;padding:5px 8px;font-size:10px;font-weight:750;background:#eef2ed;color:#59685f}.result-badge.met{background:#e7f3e9;color:#297345}.result-badge.gap{background:#fff0e7;color:#a14c30}.result-badge.verify{background:#fff6dd;color:#86630a}.result-badge.na{background:#edf0f2;color:#66727b}.criterion-requirement,.criterion-reason{font-size:10px;line-height:1.6;color:#68766d;margin:8px 0 0}.criterion-reason{color:#35463d}.criterion-review{display:flex;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid #eef0ed;padding-top:9px;margin-top:9px;font-size:10px;color:#718077}.criterion-review select{max-width:165px}.source-callout{display:grid;gap:7px;padding:12px;border:1px solid #e7ede8;border-radius:12px;background:#f8faf8;font-size:10px;line-height:1.6;color:#536359}.source-callout b{color:var(--ink)}@media(max-width:720px){.standard-grid{grid-template-columns:1fr}.criterion-heading{align-items:flex-start}}';document.head.appendChild(plannerStyle);
