const plannerBaseStatus=statusForJob;
statusForJob=function(job){const s=(job.postingStatus||job.status||'');if(/已关闭|历史职位/.test(s))return{label:'已关闭（历史样例）',cls:'gray'};if(/历史届别/.test(s))return{label:'历史届别条件',cls:'gray'};return plannerBaseStatus(job)};
const plannerProfileForCopy=profileHTML;
profileHTML=function(){let h=plannerProfileForCopy();return h.replace('学历 / 专业、毕业批次、工作许可、工作地点、语言及资格证。条件不明确时记录“待核实”，不要把不确定当作通过。','学历、经验、资格、许可、地点、工时或招聘方列出的其他必填项；多数职位并不要求所有项目。条件不清时记为“待核实”。').replace('公司通常先看学历与专业、毕业届别、工作许可、地点、成绩 / 语言、资格证等硬条件，再看实习、技能和成果。岗位间差异很大，画像里的状态需要和每条招聘公告逐项对照。','雇主筛选项因职位、地区和职业阶段而异。有的看学历或证照，有的侧重工作经验、技能或服务能力；也有职位不要求正式学历。请按招聘原文逐项对照。')};
const plannerOverviewForCopy=overviewHTML;
overviewHTML=function(){return plannerOverviewForCopy().replace('综合你的教育、实习、个人意愿与家庭期待，比较就业、升学和探索路径。','综合教育与工作经历、个人意愿、现实约束和可选的家庭支持，比较工作、学习、转型与其他路径。').replace('把兴趣变成岗位目标，并优先确认校招资格。','从兴趣、经验和工作条件出发，比较不同岗位及发展路径。').replace('比较项目要求、成本和毕业后的岗位出口。','比较学位、短训、职业资格或在职学习的成本与用途。').replace('用实习和短项目检验方向，不必一次定终身。','用短期项目、工作试验或培训验证转型方向。').replace('准备投递','比较岗位').replace('升学评估','学习 / 培训').replace('实习探索','探索 / 转型').replace('就业准备','工作 / 换岗')};
const plannerJobsForCopy=jobsHTML;
jobsHTML=function(){return plannerJobsForCopy().replace('学历、毕业批次、工作许可、语言和技能要求。','经验、资格、工作许可、地点、时间安排和岗位技能要求。')};
render();

